const req = globalThis.graphjinExecutorRequest || 'How many failed invoices does that account have?';
const hist = globalThis.graphjinHistory || [];

// Discover tables related to invoices and accounts
const searchResult = await query_catalog({ search: 'invoice account failed', limit: 10 });
console.log(searchResult);

// Find the specific table detail for invoices
const invoiceDetail = await query_catalog({ id: 'table:invoices' });
console.log(invoiceDetail);

// Execute GraphQL query to count failed invoices
const res = await execute_graphql({
  query: `{ invoices_aggregate(where: { status: { eq: "failed" } }) { count } }`
});
console.log(res);

await final('Answer how many failed invoices the account has using the aggregate count.', { result: res.data });
